public sealed class BlobArchive(BlobContainerClient container) : IHistoryArchive
{
    public async Task ArchiveAsync(IReadOnlyList<InstanceHistory> histories, CancellationToken cancellationToken)
    {
        foreach (var history in histories)
            await container.GetBlobClient($"{history.Process}/{history.Key}/{history.Entries[0].At:O}.json")
                .UploadAsync(BinaryData.FromString(history.ToJson()), overwrite: true, cancellationToken);
    }
}

